142	
143	function normalizeShareLinkMode(value: unknown): ShareLinkMode {
144		return value === "compressed-hash" || value === "local-short" || value === "portable-short"
145			? value
146			: DEFAULT_UI_SETTINGS.shareLinkMode;
147	}
148	
149	// Modes that make the session readable by anyone who receives the link. Both
150	// `portable-short` (session uploaded to the share server) and `compressed-hash`
151	// (session snapshot embedded in the URL) expose the transcript publicly. Only
152	// `local-short` keeps the data in this browser's cache, so it is not publicly
153	// resolvable by a recipient.
154	export function shareModeExposesDataPublicly(mode: ShareLinkMode): boolean {
155		return mode === "portable-short" || mode === "compressed-hash";
156	}
