158	function normalizeAlternativeResponseChance(value: unknown): number {
159		const numeric = typeof value === "number" ? value : Number(value);
160		if (!Number.isFinite(numeric)) return DEFAULT_UI_SETTINGS.alternativeResponseChance;
161		return Math.max(0, Math.min(1, numeric));
162	}
