164	type LegacyUiSettingsInput = Partial<KeatingUiSettings>
165		& Partial<Record<LegacyGroundingKey, "auto" | "off">>
166		& { schemaVersion?: number };
167	
168	function normalizeSettings(value: LegacyUiSettingsInput | null): KeatingUiSettings {
169		const webSearch =
170			value?.webSearch === "off" || (value?.webSearch === undefined && value?.[LEGACY_GOOGLE_GROUNDING_KEY] === "off")
171				? "off"
172				: DEFAULT_UI_SETTINGS.webSearch;
173	
174		return {
175			showToolUi: value?.showToolUi ?? DEFAULT_UI_SETTINGS.showToolUi,
176			autoOpenArtifacts: value?.autoOpenArtifacts ?? DEFAULT_UI_SETTINGS.autoOpenArtifacts,
177			limitInlineArtifactPreviews: value?.limitInlineArtifactPreviews ?? DEFAULT_UI_SETTINGS.limitInlineArtifactPreviews,
178			showRawErrors: value?.showRawErrors ?? DEFAULT_UI_SETTINGS.showRawErrors,
179			showReasoning: value?.showReasoning ?? DEFAULT_UI_SETTINGS.showReasoning,
180			autoExpandReasoning: value?.autoExpandReasoning === true,
181			reasoningLevel: value?.reasoningLevel ?? DEFAULT_UI_SETTINGS.reasoningLevel,
182			animationRenderer: "hyperframes",
183			fontFamily:
184				value?.fontFamily === "space-mono" || value?.fontFamily === "roboto" || value?.fontFamily === "jetbrains-mono"
185					? value.fontFamily
186					: DEFAULT_UI_SETTINGS.fontFamily,
187			shareLinkMode: normalizeShareLinkMode(value?.shareLinkMode),
188			shareWarningAcknowledged: value?.shareWarningAcknowledged === true,
189			// Older builds shipped either 5% or 0% as automatic defaults. Version 3
190			// makes comparisons deliberately rare at 1%, while preserving every other
191			// explicitly chosen probability.
192			alternativeResponseChance:
193				value?.schemaVersion !== UI_SETTINGS_SCHEMA_VERSION
194					&& (value?.alternativeResponseChance === 0.05 || value?.alternativeResponseChance === 0)
195					? DEFAULT_UI_SETTINGS.alternativeResponseChance
196					: normalizeAlternativeResponseChance(value?.alternativeResponseChance),
197			userProfileImage: typeof value?.userProfileImage === "string" && value.userProfileImage.startsWith("data:image/") ? value.userProfileImage : DEFAULT_UI_SETTINGS.userProfileImage,
198			imageGenerator: isImageGeneratorId(value?.imageGenerator) ? value.imageGenerator : DEFAULT_UI_SETTINGS.imageGenerator,
199			imageModel: typeof value?.imageModel === "string" ? value.imageModel : DEFAULT_UI_SETTINGS.imageModel,
200			imageSize: typeof value?.imageSize === "string" ? value.imageSize : DEFAULT_UI_SETTINGS.imageSize,
201			imageQuality: typeof value?.imageQuality === "string" ? value.imageQuality : DEFAULT_UI_SETTINGS.imageQuality,
202			localImageBaseUrl: typeof value?.localImageBaseUrl === "string" ? value.localImageBaseUrl : DEFAULT_UI_SETTINGS.localImageBaseUrl,
203			webSearch,
