208	export function applyKeatingUiTypography(fontFamily: UiFontFamily) {
209		if (typeof document === "undefined") return;
210		const stacks = FONT_STACKS[fontFamily] ?? FONT_STACKS.roboto;
211		const root = document.documentElement;
212		root.style.setProperty("--font-sans", stacks.sans);
213		root.style.setProperty("--font-serif", stacks.serif);
214		root.style.setProperty("--font-mono", stacks.mono);
215	}
