217	export function loadKeatingUiSettings(): KeatingUiSettings {
218		if (typeof localStorage === "undefined") return DEFAULT_UI_SETTINGS;
219		try {
220			const raw = localStorage.getItem(STORAGE_KEY);
221			if (!raw) return DEFAULT_UI_SETTINGS;
222			return normalizeSettings(JSON.parse(raw) as LegacyUiSettingsInput);
223		} catch (error) {
224			console.warn("Failed to load Keating UI settings:", error);
225			return DEFAULT_UI_SETTINGS;
226		}
227	}
228	
229	export function saveKeatingUiSettings(next: KeatingUiSettings) {
230		const normalized = normalizeSettings(next);
231		try {
232			localStorage.setItem(STORAGE_KEY, JSON.stringify({ ...normalized, schemaVersion: UI_SETTINGS_SCHEMA_VERSION }));
233		} catch (error) {
234			console.warn("Failed to save Keating UI settings:", error);
235		}
236		window.dispatchEvent(new CustomEvent<KeatingUiSettings>(SETTINGS_CHANGED_EVENT, { detail: normalized }));
237	}
238	
239	export function subscribeKeatingUiSettings(callback: (settings: KeatingUiSettings) => void) {
240		return subscribeLocalSetting({ event: SETTINGS_CHANGED_EVENT, load: loadKeatingUiSettings }, callback);
241	}
