154	function providerErrorMessage(payload: unknown, fallback: string): string {
155	  if (typeof payload !== "object" || payload === null) return fallback;
156	  const record = payload as Record<string, unknown>;
157	  const error = record.error;
158	  if (typeof error === "string" && error.trim()) return error;
159	  if (typeof error === "object" && error !== null) {
160	    const message = (error as Record<string, unknown>).message;
161	    if (typeof message === "string" && message.trim()) return message;
162	  }
163	  const message = record.message;
164	  return typeof message === "string" && message.trim() ? message : fallback;
