167	function extractProviderText(settings: ProviderSettings, payload: unknown): string {
168	  const record = payload as Record<string, any>;
169	  if (settings.provider === "openai") {
170	    if (typeof record.output_text === "string" && record.output_text.trim()) return record.output_text.trim();
171	    const text = Array.isArray(record.output)
172	      ? record.output
173	        .flatMap((item: any) => Array.isArray(item?.content) ? item.content : [])
174	        .filter((part: any) => part?.type === "output_text" && typeof part?.text === "string")
175	        .map((part: any) => part.text)
176	        .join("\n")
177	      : "";
178	    if (text.trim()) return text.trim();
179	  } else if (settings.provider === "anthropic") {
180	    const text = Array.isArray(record.content)
181	      ? record.content.filter((block: any) => block?.type === "text").map((block: any) => block.text).join("\n")
182	      : "";
183	    if (text.trim()) return text.trim();
184	  } else if (settings.provider === "google") {
185	    const text = record.candidates?.[0]?.content?.parts
186	      ?.map((part: any) => typeof part?.text === "string" ? part.text : "")
187	      .join("\n");
188	    if (typeof text === "string" && text.trim()) return text.trim();
189	  } else {
190	    const content = record.choices?.[0]?.message?.content;
191	    if (typeof content === "string" && content.trim()) return content.trim();
192	    if (Array.isArray(content)) {
193	      const text = content.map((part: any) => part?.text ?? "").join("\n");
