206	export function createSseParser(): (chunk: string) => string[] {
207	  let buffer = "";
208	  return (chunk: string) => {
209	    buffer += chunk;
210	    const events: string[] = [];
211	    for (let match = EVENT_SEPARATOR.exec(buffer); match; match = EVENT_SEPARATOR.exec(buffer)) {
212	      const rawEvent = buffer.slice(0, match.index);
213	      buffer = buffer.slice(match.index + match[0].length);
214	      const data = rawEvent
215	        .split(/\r?\n/)
216	        .filter((line) => line.startsWith("data:"))
217	        .map((line) => line.slice(5).trim())
