279	export interface StreamCompletionOptions extends ProviderRequestOptions {
280	  /** Called with each incremental text chunk as it arrives. */
281	  onDelta?: (delta: string, accumulated: string) => void;
282	  fetchImpl?: FetchLike;
283	}
