285	/**
286	 * Streams a completion, invoking `onDelta` per chunk and resolving with the
287	 * full text. Falls back to a single non-streamed read when the provider
288	 * responds without a readable body.
289	 */
290	export async function streamCompletion(
291	  settings: ProviderSettings,
292	  apiKey: string | null,
293	  messages: ChatMessage[],
294	  options: StreamCompletionOptions = {},
295	): Promise<string> {
296	  const { onDelta, fetchImpl = fetch, ...requestOptions } = options;
297	  const request = buildProviderRequest(settings, apiKey, messages, { ...requestOptions, stream: true });
298	  const response = await fetchImpl(request.url, request.init);
299	
300	  if (!response.ok) await throwProviderError(response);
301	
302	  const body = response.body;
303	  if (!body) {
304	    // No readable stream on this platform — take the whole payload at once.
305	    return wholePayloadFallback(settings, await response.text(), onDelta);
306	  }
307	
308	  const decoder = new TextDecoder();
309	  const parse = createSseParser();
310	  const reader = body.getReader();
311	  let accumulated = "";
312	  let raw = "";
313	
314	  try {
315	    while (true) {
316	      const { done, value } = await reader.read();
317	      if (done) break;
318	      const chunk = decoder.decode(value, { stream: true });
319	      raw += chunk;
320	      for (const data of parse(chunk)) {
321	        const delta = extractStreamDelta(settings, data);
322	        if (!delta) continue;
323	        accumulated += delta;
324	        onDelta?.(delta, accumulated);
325	      }
326	    }
327	  } finally {
328	    reader.releaseLock();
329	  }
330	
331	  const trimmed = accumulated.trim();
332	  if (trimmed) return trimmed;
333	
334	  // Some OpenAI-compatible servers (local runtimes especially) ignore
335	  // `stream: true` and answer with one plain JSON body instead of SSE.
336	  return wholePayloadFallback(settings, raw, onDelta);
337	}
338	
339	function wholePayloadFallback(
340	  settings: ProviderSettings,
341	  text: string,
342	  onDelta?: (delta: string, accumulated: string) => void,
343	): string {
344	  let payload: unknown;
345	  try {
346	    payload = text.trim() ? JSON.parse(text) : {};
347	  } catch {
348	    throw new Error("The provider returned a response without readable text.");
349	  }
350	  const content = extractProviderText(settings, payload);
351	  onDelta?.(content, content);
352	  return content;
353	}
354	
355	export async function requestCompletion(
356	  settings: ProviderSettings,
357	  apiKey: string | null,
358	  messages: ChatMessage[],
359	  signal?: AbortSignal,
360	  fetchImpl: FetchLike = fetch,
361	  systemPrompt?: string,
362	): Promise<string> {
363	  const request = buildProviderRequest(settings, apiKey, messages, { signal, systemPrompt });
364	  const response = await fetchImpl(request.url, request.init);
365	  const responseText = await response.text();
366	  let payload: unknown = {};
367	  try {
368	    payload = responseText ? JSON.parse(responseText) : {};
369	  } catch {
370	    if (!response.ok) throw new Error(`Provider request failed with HTTP ${response.status}.`);
371	    throw new Error("The provider returned an invalid JSON response.");
372	  }
373	
374	  if (!response.ok) {
375	    throw new Error(providerErrorMessage(payload, `Provider request failed with HTTP ${response.status}.`));
376	  }
377	  return extractProviderText(settings, payload);
378	}
