/**
 * The slice of the course contract this app reads. The server owns the full
 * schema (web/src/courses/contracts.ts); these are hand-mirrored structural
 * types for the read paths the native client uses, so the app never needs zod
 * on device. Anything unmodelled is simply ignored.
 */

export type CourseRole = "owner" | "teacher" | "student" | "peer";
export type TeacherAccess = "private" | "requested" | "full";
export type CourseMaterialKind = "document" | "image" | "link" | "note" | "anki";

export interface CourseSessionAccount {
  id: string;
  displayName: string;
  mode: "development" | "local" | "hosted";
}

export interface CourseListItem {
  id: string;
  title: string;
  description: string;
  role: CourseRole;
  memberCount: number;
  lessonCount: number;
  completedLessons: number;
  updatedAt: string;
}

export interface CourseMaterial {
  id: string;
  kind: CourseMaterialKind;
  title: string;
  description?: string;
  url?: string;
  fileName?: string;
  mimeType?: string;
  sizeBytes?: number;
  lessonId?: string;
  createdAt: string;
}

export interface CourseLesson {
  id: string;
  title: string;
  summary: string;
  estimatedMinutes?: number;
  objectives: string[];
  reading: string;
  materialIds: string[];
}

export interface CourseModule {
  id: string;
  title: string;
  description: string;
  lessons: CourseLesson[];
}

export interface CourseProgress {
  activeLessonId?: string;
  completedLessonIds: string[];
  lastActiveAt: string;
}

export interface CourseMember {
  accountId: string;
  displayName: string;
  role: CourseRole;
  teacherAccess: TeacherAccess;
  progress: CourseProgress;
}

export interface Course {
  id: string;
  title: string;
  description: string;
  outcomes: string[];
  updatedAt: string;
  revision: number;
  modules: CourseModule[];
  materials: CourseMaterial[];
  members: CourseMember[];
}

export interface CoursePermissions {
  canEditCourse: boolean;
  canInvite: boolean;
  canReview: boolean;
  canEditDeck: boolean;
  canRequestTeacherAccess: boolean;
}

export interface CourseViewerSnapshot {
  course: Course;
  viewer: CourseMember;
  permissions: CoursePermissions;
}

const ROLES = new Set<CourseRole>(["owner", "teacher", "student", "peer"]);
const MATERIAL_KINDS = new Set<CourseMaterialKind>(["document", "image", "link", "note", "anki"]);

function str(value: unknown, fallback = ""): string {
  return typeof value === "string" ? value : fallback;
}

function strArray(value: unknown): string[] {
  return Array.isArray(value) ? value.filter((entry): entry is string => typeof entry === "string") : [];
}

function record(value: unknown): Record<string, unknown> {
  return typeof value === "object" && value !== null ? value as Record<string, unknown> : {};
}

function role(value: unknown): CourseRole {
  return ROLES.has(value as CourseRole) ? value as CourseRole : "student";
}

export function normalizeCourseListItem(value: unknown): CourseListItem {
  const item = record(value);
  return {
    id: str(item.id),
    title: str(item.title, "Untitled course"),
    description: str(item.description),
    role: role(item.role),
    memberCount: typeof item.memberCount === "number" ? item.memberCount : 0,
    lessonCount: typeof item.lessonCount === "number" ? item.lessonCount : 0,
    completedLessons: typeof item.completedLessons === "number" ? item.completedLessons : 0,
    updatedAt: str(item.updatedAt),
  };
}

function normalizeMaterial(value: unknown): CourseMaterial {
  const material = record(value);
  const kind = MATERIAL_KINDS.has(material.kind as CourseMaterialKind)
    ? material.kind as CourseMaterialKind
    : "note";
  return {
    id: str(material.id),
    kind,
    title: str(material.title, "Untitled material"),
    description: typeof material.description === "string" ? material.description : undefined,
    url: typeof material.url === "string" ? material.url : undefined,
    fileName: typeof material.fileName === "string" ? material.fileName : undefined,
    mimeType: typeof material.mimeType === "string" ? material.mimeType : undefined,
    sizeBytes: typeof material.sizeBytes === "number" ? material.sizeBytes : undefined,
    lessonId: typeof material.lessonId === "string" ? material.lessonId : undefined,
    createdAt: str(material.createdAt),
  };
}

function normalizeLesson(value: unknown): CourseLesson {
  const lesson = record(value);
  return {
    id: str(lesson.id),
    title: str(lesson.title, "Untitled lesson"),
    summary: str(lesson.summary),
    estimatedMinutes: typeof lesson.estimatedMinutes === "number" ? lesson.estimatedMinutes : undefined,
    objectives: strArray(lesson.objectives),
    reading: str(lesson.reading),
    materialIds: strArray(lesson.materialIds),
  };
}

function normalizeMember(value: unknown): CourseMember {
  const member = record(value);
  const progress = record(member.progress);
  return {
    accountId: str(member.accountId),
    displayName: str(member.displayName, "Learner"),
    role: role(member.role),
    teacherAccess: member.teacherAccess === "full" || member.teacherAccess === "requested"
      ? member.teacherAccess
      : "private",
    progress: {
      activeLessonId: typeof progress.activeLessonId === "string" ? progress.activeLessonId : undefined,
      completedLessonIds: strArray(progress.completedLessonIds),
      lastActiveAt: str(progress.lastActiveAt),
    },
  };
}

export function normalizeCourseSnapshot(value: unknown): CourseViewerSnapshot {
  const snapshot = record(value);
  const course = record(snapshot.course);
  const permissions = record(snapshot.permissions);
  return {
    course: {
      id: str(course.id),
      title: str(course.title, "Untitled course"),
      description: str(course.description),
      outcomes: strArray(course.outcomes),
      updatedAt: str(course.updatedAt),
      revision: typeof course.revision === "number" ? course.revision : 0,
      modules: (Array.isArray(course.modules) ? course.modules : []).map((module) => {
        const entry = record(module);
        return {
          id: str(entry.id),
          title: str(entry.title, "Untitled module"),
          description: str(entry.description),
          lessons: (Array.isArray(entry.lessons) ? entry.lessons : []).map(normalizeLesson),
        };
      }),
      materials: (Array.isArray(course.materials) ? course.materials : []).map(normalizeMaterial),
      members: (Array.isArray(course.members) ? course.members : []).map(normalizeMember),
    },
    viewer: normalizeMember(snapshot.viewer),
    permissions: {
      canEditCourse: permissions.canEditCourse === true,
      canInvite: permissions.canInvite === true,
      canReview: permissions.canReview === true,
      canEditDeck: permissions.canEditDeck === true,
      canRequestTeacherAccess: permissions.canRequestTeacherAccess === true,
    },
  };
}

/** Lessons across every module, in course order. */
export function allCourseLessons(course: Pick<Course, "modules">): CourseLesson[] {
  return course.modules.flatMap((module) => module.lessons);
}

/**
 * A minimal cookie jar for the course API.
 *
 * Course auth is a server-set session cookie. React Native's networking stack
 * usually persists cookies natively, but that is platform-dependent and
 * invisible to tests, so the client also keeps its own jar: it records any
 * `set-cookie` it can see and replays it on later requests. Belt and braces —
 * whichever mechanism works, the session survives an app restart.
 *
 * Parsing lives here, free of storage and React Native imports, so it can be
 * exercised directly under `bun test`.
 */

export type CookieJar = Readonly<Record<string, string>>;

/**
 * Pulls `name=value` pairs out of a `set-cookie` header, ignoring attributes
 * (`Path`, `HttpOnly`, `Max-Age`, …). React Native folds multiple cookies into
 * one comma-joined header, so splitting has to skip the commas inside an
 * `Expires=Wed, 09 Jun 2027 …` date.
 */
export function parseSetCookie(header: string | null | undefined): Record<string, string> {
  if (!header) return {};
  const jar: Record<string, string> = {};
  for (const chunk of splitCookieHeader(header)) {
    const pair = chunk.split(";", 1)[0]?.trim();
    if (!pair) continue;
    const separator = pair.indexOf("=");
    if (separator <= 0) continue;
    const name = pair.slice(0, separator).trim();
    const value = pair.slice(separator + 1).trim();
    // An empty value with an expiry in the past is a deletion; drop the name
    // rather than replaying a blank cookie.
    if (name) jar[name] = value;
  }
  return jar;
}

function splitCookieHeader(header: string): string[] {
  const parts: string[] = [];
  let current = "";
  for (let index = 0; index < header.length; index += 1) {
    const character = header[index]!;
    if (character !== ",") {
      current += character;
      continue;
    }
    // A comma starts a new cookie only when what follows looks like `name=`
    // before the next `;` — otherwise it belongs to a date inside an attribute.
    const rest = header.slice(index + 1);
    if (/^\s*[^=;,\s]+=/.test(rest)) {
      parts.push(current);
      current = "";
    } else {
      current += character;
    }
  }
  if (current.trim()) parts.push(current);
  return parts;
}

export function mergeCookies(jar: CookieJar, incoming: Record<string, string>): CookieJar {
  const next: Record<string, string> = { ...jar };
  for (const [name, value] of Object.entries(incoming)) {
    if (value === "") delete next[name];
    else next[name] = value;
  }
  return next;
}

/** Serialises the jar into a `Cookie` request header, or `null` when empty. */
export function serializeCookies(jar: CookieJar): string | null {
  const entries = Object.entries(jar);
  if (entries.length === 0) return null;
  return entries.map(([name, value]) => `${name}=${value}`).join("; ");
}

import AsyncStorage from "@react-native-async-storage/async-storage";
import { KEATING_WEB_ORIGIN } from "../product-links";
import { type CookieJar, mergeCookies, parseSetCookie, serializeCookies } from "./cookie-jar";
import {
  type CourseListItem,
  type CourseSessionAccount,
  type CourseViewerSnapshot,
  normalizeCourseListItem,
  normalizeCourseSnapshot,
} from "./types";

const COOKIE_STORAGE_KEY = "keating.mobile.course-cookies";

/** A course request that failed with the server's own error code attached. */
export class CourseApiError extends Error {
  constructor(readonly status: number, message: string, readonly code: string) {
    super(message);
    this.name = "CourseApiError";
  }

  /** True when the learner is not a member, or the invite did not apply. */
  get isAccessProblem(): boolean {
    return this.status === 401 || this.status === 403 || this.status === 404;
  }
}

let jar: CookieJar | null = null;

async function loadJar(): Promise<CookieJar> {
  if (jar) return jar;
  try {
    const raw = await AsyncStorage.getItem(COOKIE_STORAGE_KEY);
    jar = raw ? JSON.parse(raw) as CookieJar : {};
  } catch {
    jar = {};
  }
  return jar;
}

async function rememberCookies(header: string | null): Promise<void> {
  const incoming = parseSetCookie(header);
  if (Object.keys(incoming).length === 0) return;
  const next = mergeCookies(await loadJar(), incoming);
  jar = next;
  await AsyncStorage.setItem(COOKIE_STORAGE_KEY, JSON.stringify(next)).catch(() => undefined);
}

/** Drops the stored session; the next request starts a fresh course account. */
export async function clearCourseSession(): Promise<void> {
  jar = {};
  await AsyncStorage.removeItem(COOKIE_STORAGE_KEY).catch(() => undefined);
}

export interface CourseRequestOptions {
  signal?: AbortSignal;
  fetchImpl?: typeof fetch;
}

async function request<T>(
  path: string,
  init: RequestInit,
  normalize: (payload: unknown) => T,
  options: CourseRequestOptions = {},
): Promise<T> {
  const { signal, fetchImpl = fetch } = options;
  const cookie = serializeCookies(await loadJar());
  const headers: Record<string, string> = {
    Accept: "application/json",
    ...(init.body ? { "Content-Type": "application/json" } : {}),
    ...(cookie ? { Cookie: cookie } : {}),
  };

  let response: Response;
  try {
    response = await fetchImpl(`${KEATING_WEB_ORIGIN}/api/courses${path}`, { ...init, headers, signal });
  } catch (error) {
    if (error instanceof Error && error.name === "AbortError") throw error;
    throw new CourseApiError(0, "Could not reach Keating. Check your connection.", "course_offline");
  }

  await rememberCookies(response.headers.get("set-cookie"));

  const text = await response.text();
  let payload: unknown = null;
  try {
    payload = text ? JSON.parse(text) : null;
  } catch {
    payload = null;
  }

  if (!response.ok) {
    const body = (payload ?? {}) as Record<string, unknown>;
    const data = (body.data ?? {}) as Record<string, unknown>;
    const message = typeof body.statusMessage === "string" && body.statusMessage
      ? body.statusMessage
      : typeof body.message === "string" && body.message
        ? body.message
        : `The course server returned HTTP ${response.status}.`;
    throw new CourseApiError(
      response.status,
      message,
      typeof data.code === "string" ? data.code : "course_request_failed",
    );
  }

  return normalize(payload);
}

export function fetchCourseSession(options?: CourseRequestOptions): Promise<CourseSessionAccount> {
  return request("/session", { method: "GET" }, (payload) => {
    const account = ((payload ?? {}) as Record<string, unknown>).account as Record<string, unknown> ?? {};
    return {
      id: typeof account.id === "string" ? account.id : "",
      displayName: typeof account.displayName === "string" ? account.displayName : "Learner",
      mode: account.mode === "hosted" || account.mode === "development" ? account.mode : "local",
    };
  }, options);
}

export function fetchCourses(options?: CourseRequestOptions): Promise<CourseListItem[]> {
  return request("", { method: "GET" }, (payload) => {
    const courses = ((payload ?? {}) as Record<string, unknown>).courses;
    return Array.isArray(courses) ? courses.map(normalizeCourseListItem) : [];
  }, options);
}

export function fetchCourse(courseId: string, options?: CourseRequestOptions): Promise<CourseViewerSnapshot> {
  return request(`/${encodeURIComponent(courseId)}`, { method: "GET" }, normalizeCourseSnapshot, options);
}

/**
 * Redeems an invite code. `acceptTeacherAccess` is the learner's explicit
 * consent to let course teachers see their work, so it is always passed
 * through from a deliberate choice rather than defaulted on.
 */
export function joinCourse(
  inviteCode: string,
  acceptTeacherAccess: boolean,
  options?: CourseRequestOptions,
): Promise<CourseViewerSnapshot> {
  return request(
    `/join/${encodeURIComponent(inviteCode)}`,
    { method: "POST", body: JSON.stringify({ acceptTeacherAccess }) },
    normalizeCourseSnapshot,
    options,
  );
}

/** Absolute URL for a material the app hands off to the browser. */
export function courseMaterialUrl(courseId: string, materialId: string): string {
  return `${KEATING_WEB_ORIGIN}/api/courses/${encodeURIComponent(courseId)}/materials/${encodeURIComponent(materialId)}`;
}

