import Ionicons from "@expo/vector-icons/Ionicons";
import { useRouter } from "expo-router";
import { useCallback, useEffect, useRef, useState } from "react";
import {
  ActivityIndicator,
  FlatList,
  Modal,
  Pressable,
  RefreshControl,
  StyleSheet,
  Switch,
  Text,
  TextInput,
  View,
} from "react-native";
import { Button } from "@/components/Buttons";
import { EmptyState } from "@/components/EmptyState";
import { Screen } from "@/components/Screen";
import { radii, spacing, useKeatingTheme } from "@/constants/theme";
import {
  CourseApiError,
  fetchCourses,
  fetchCourseSession,
  joinCourse,
} from "@/lib/courses/client";
import type { CourseListItem, CourseSessionAccount } from "@/lib/courses/types";

export default function CoursesScreen() {
  const theme = useKeatingTheme();
  const styles = createStyles(theme);
  const router = useRouter();
  const [courses, setCourses] = useState<CourseListItem[] | null>(null);
  const [account, setAccount] = useState<CourseSessionAccount | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [refreshing, setRefreshing] = useState(false);
  const [joinOpen, setJoinOpen] = useState(false);
  const loadController = useRef<AbortController | null>(null);

  const load = useCallback(async (mode: "initial" | "refresh") => {
    loadController.current?.abort();
    const controller = new AbortController();
    loadController.current = controller;
    if (mode === "refresh") setRefreshing(true);
    setError(null);
    try {
      const [session, list] = await Promise.all([
        fetchCourseSession({ signal: controller.signal }),
        fetchCourses({ signal: controller.signal }),
      ]);
      if (controller.signal.aborted) return;
      setAccount(session);
      setCourses(list);
    } catch (caught) {
      if (controller.signal.aborted || (caught instanceof Error && caught.name === "AbortError")) return;
      setError(caught instanceof Error ? caught.message : "Could not load your courses.");
      // Keep whatever list is already on screen; a failed refresh should not
      // blank out courses the learner was reading.
      setCourses((current) => current ?? []);
    } finally {
      if (loadController.current === controller) loadController.current = null;
      setRefreshing(false);
    }
  }, []);

  useEffect(() => {
    void load("initial");
    return () => loadController.current?.abort();
  }, [load]);

  return (
    <Screen
      scroll={false}
      title="Courses"
      subtitle={account ? `Signed in as ${account.displayName}` : "Structured learning with your class or study group"}
      action={<Button compact variant="secondary" onPress={() => setJoinOpen(true)}>Join</Button>}
    >
      {error ? (
        <View style={styles.errorBanner} accessibilityRole="alert">
          <Text style={styles.errorText}>{error}</Text>
          <Button compact variant="quiet" onPress={() => void load("refresh")}>Try again</Button>
        </View>
      ) : null}

      {courses === null ? (
        <View style={styles.loading}>
          <ActivityIndicator color={theme.colors.primaryText} />
          <Text style={styles.loadingText}>Loading your courses…</Text>
        </View>
      ) : (
        <FlatList
          data={courses}
          keyExtractor={(course) => course.id}
          contentContainerStyle={styles.list}
          refreshControl={(
            <RefreshControl
              refreshing={refreshing}
              onRefresh={() => void load("refresh")}
              tintColor={theme.colors.primaryText}
            />
          )}
          renderItem={({ item }) => (
            <CourseRow course={item} onPress={() => router.push(`/course/${item.id}`)} />
          )}
          ListEmptyComponent={(
            <EmptyState
              title="No courses yet"
              body="Join a course with the invite code your teacher or study group shared."
              action={<Button onPress={() => setJoinOpen(true)}>Join a course</Button>}
            />
          )}
        />
      )}

      <JoinCourseSheet
        visible={joinOpen}
        onClose={() => setJoinOpen(false)}
        onJoined={(courseId) => {
          setJoinOpen(false);
          void load("refresh");
          router.push(`/course/${courseId}`);
        }}
      />
    </Screen>
  );
}

function CourseRow({ course, onPress }: { course: CourseListItem; onPress: () => void }) {
  const theme = useKeatingTheme();
  const styles = createStyles(theme);
  const progress = course.lessonCount > 0
    ? Math.round((course.completedLessons / course.lessonCount) * 100)
    : 0;
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={`${course.title}. ${course.completedLessons} of ${course.lessonCount} lessons done.`}
      onPress={onPress}
      style={({ pressed }) => [styles.card, pressed && styles.cardPressed]}
    >
      <View style={styles.cardHeader}>
        <Text numberOfLines={2} style={styles.cardTitle}>{course.title}</Text>
        <Text style={styles.role}>{course.role.toUpperCase()}</Text>
      </View>
      {course.description ? (
        <Text numberOfLines={2} style={styles.cardBody}>{course.description}</Text>
      ) : null}
      <View style={styles.progressTrack}>
        <View style={[styles.progressFill, { width: `${progress}%` }]} />
      </View>
      <Text style={styles.meta}>
        {course.completedLessons} / {course.lessonCount} lessons · {course.memberCount}{" "}
        {course.memberCount === 1 ? "member" : "members"}
      </Text>
    </Pressable>
  );
}

function JoinCourseSheet({
  visible,
  onClose,
  onJoined,
}: {
  visible: boolean;
  onClose: () => void;
  onJoined: (courseId: string) => void;
}) {
  const theme = useKeatingTheme();
  const styles = createStyles(theme);
  const [code, setCode] = useState("");
  const [acceptTeacherAccess, setAcceptTeacherAccess] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!visible) return;
    setCode("");
    setAcceptTeacherAccess(false);
    setError(null);
  }, [visible]);

  const submit = async () => {
    const trimmed = code.trim();
    if (!trimmed) return;
    setBusy(true);
    setError(null);
    try {
      const snapshot = await joinCourse(trimmed, acceptTeacherAccess);
      onJoined(snapshot.course.id);
    } catch (caught) {
      setError(caught instanceof CourseApiError
        ? caught.message
        : "Could not join this course. Check the code and try again.");
    } finally {
      setBusy(false);
    }
  };

  return (
    <Modal visible={visible} transparent animationType="slide" statusBarTranslucent onRequestClose={onClose}>
      <View style={styles.overlay}>
        <Pressable accessibilityRole="button" accessibilityLabel="Close join course" style={styles.scrim} onPress={onClose} />
        <View accessibilityViewIsModal accessibilityLabel="Join a course" style={styles.sheet}>
          <Text style={styles.sheetTitle}>Join a course</Text>
          <Text style={styles.sheetBody}>Paste the invite code your teacher or study group shared.</Text>
          <TextInput
            accessibilityLabel="Invite code"
            autoCapitalize="none"
            autoCorrect={false}
            autoFocus
            placeholder="Invite code"
            placeholderTextColor={theme.colors.textFaint}
            value={code}
            onChangeText={setCode}
            onSubmitEditing={() => void submit()}
            style={styles.input}
          />
          {/*
            Teacher access is the learner's own disclosure decision, so it is
            off until they turn it on — never implied by joining.
          */}
          <View style={styles.consentRow}>
            <View style={styles.consentCopy}>
              <Text style={styles.consentTitle}>Let teachers see my work</Text>
              <Text style={styles.consentBody}>
                Shares your submissions and progress with course teachers. You can join without this.
              </Text>
            </View>
            <Switch
              accessibilityLabel="Let teachers see my work"
              value={acceptTeacherAccess}
              onValueChange={setAcceptTeacherAccess}
              trackColor={{ false: theme.colors.border, true: theme.colors.primary }}
              thumbColor={acceptTeacherAccess ? theme.colors.primaryInk : theme.colors.textFaint}
            />
          </View>
          {error ? <Text accessibilityRole="alert" style={styles.errorText}>{error}</Text> : null}
          <View style={styles.sheetActions}>
            <Button loading={busy} disabled={!code.trim()} onPress={() => void submit()}>Join course</Button>
            <Button variant="quiet" onPress={onClose}>Cancel</Button>
          </View>
        </View>
      </View>
    </Modal>
  );
}

