  visible: boolean;
  onClose: () => void;
  onJoined: (courseId: string) => void;
}) {
  const theme = useKeatingTheme();
  const styles = createStyles(theme);
  const [code, setCode] = useState("");
  const [acceptTeacherAccess, setAcceptTeacherAccess] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!visible) return;
    setCode("");
    setAcceptTeacherAccess(false);
    setError(null);
  }, [visible]);

  const submit = async () => {
    const trimmed = code.trim();
    if (!trimmed) return;
    setBusy(true);
    setError(null);
    try {
      const snapshot = await joinCourse(trimmed, acceptTeacherAccess);
      onJoined(snapshot.course.id);
    } catch (caught) {
      setError(caught instanceof CourseApiError
        ? caught.message
        : "Could not join this course. Check the code and try again.");
    } finally {
      setBusy(false);
    }
  };

  return (
    <Modal visible={visible} transparent animationType="slide" statusBarTranslucent onRequestClose={onClose}>
      <View style={styles.overlay}>
        <Pressable accessibilityRole="button" accessibilityLabel="Close join course" style={styles.scrim} onPress={onClose} />
        <View accessibilityViewIsModal accessibilityLabel="Join a course" style={styles.sheet}>
          <Text style={styles.sheetTitle}>Join a course</Text>
          <Text style={styles.sheetBody}>Paste the invite code your teacher or study group shared.</Text>
          <TextInput
            accessibilityLabel="Invite code"
            autoCapitalize="none"
            autoCorrect={false}
            autoFocus
            placeholder="Invite code"
            placeholderTextColor={theme.colors.textFaint}
            value={code}
            onChangeText={setCode}
            onSubmitEditing={() => void submit()}
            style={styles.input}
          />
          {/*
            Teacher access is the learner's own disclosure decision, so it is
            off until they turn it on — never implied by joining.
          */}
          <View style={styles.consentRow}>
            <View style={styles.consentCopy}>
              <Text style={styles.consentTitle}>Let teachers see my work</Text>
              <Text style={styles.consentBody}>
                Shares your submissions and progress with course teachers. You can join without this.
              </Text>
            </View>
            <Switch
              accessibilityLabel="Let teachers see my work"
              value={acceptTeacherAccess}
              onValueChange={setAcceptTeacherAccess}
              trackColor={{ false: theme.colors.border, true: theme.colors.primary }}
              thumbColor={acceptTeacherAccess ? theme.colors.primaryInk : theme.colors.textFaint}
            />
          </View>
          {error ? <Text accessibilityRole="alert" style={styles.errorText}>{error}</Text> : null}
          <View style={styles.sheetActions}>
            <Button loading={busy} disabled={!code.trim()} onPress={() => void submit()}>Join course</Button>
            <Button variant="quiet" onPress={onClose}>Cancel</Button>
          </View>
        </View>
      </View>
    </Modal>
  );
}

